<?php require __DIR__.'/core/bootstrap.php';$error='';if(is_post()){verify_csrf();try{if(!rate_limit('contact',5,3600))throw new InvalidArgumentException('Limite de mensagens atingido. Tente mais tarde.');$name=input('name',120);$email=strtolower(input('email',190));$server=input('server',150);$version=input('version',40);$plan=input('plan',100);$body=input('body',6000);if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||$server===''||$body==='')throw new InvalidArgumentException('Preencha nome, e-mail, servidor e mensagem.');run('INSERT INTO leads (name,email,server_name,version,plan,body,status,created_at) VALUES (?,?,?,?,?,?,\'new\',?)',[$name,$email,$server,$version,$plan,$body,date('Y-m-d H:i:s')]);flash('Briefing enviado. A equipe poderá consultar sua solicitação no painel.');go('contato.php');}catch(InvalidArgumentException $ex){$error=$ex->getMessage();}}$pageTitle='Contato e orçamento — S7VEN';require ROOT.'/includes/header.php';?><main class="readable"><div class="eyebrow">VAMOS CONSTRUIR SEU PROJETO</div><h1>O próximo nível começa aqui.</h1><p>Envie seu briefing para nossa central. Contato: <?=e(setting('contact_email'))?></p><?php $wa=setting('whatsapp');if(preg_match('/^\d{10,15}$/',$wa)):?><a class="btn outline" href="https://wa.me/<?=e($wa)?>" target="_blank" rel="noopener noreferrer">Conversar no WhatsApp ↗</a><?php endif;if($error):?><div class="errors"><?=e($error)?></div><?php endif;?><form method="post"><?php csrf();?><div class="grid-two"><label class="field">Seu nome<input name="name" required maxlength="120" value="<?=e(user()['name']??'')?>"></label><label class="field">E-mail<input name="email" type="email" required maxlength="190" value="<?=e(user()['email']??'')?>"></label><label class="field">Nome do servidor<input name="server" required maxlength="150"></label><label class="field">Versão<select name="version"><option>97d + 99i</option><option>Season 2</option><option>Season 6</option><option>Season 19+</option><option>Outra versão</option></select></label><label class="field">Plano / solução<input name="plan" maxlength="100" value="<?=e(substr((string)($_GET['plano']??'Personalizado'),0,100))?>"></label></div><label class="field">Conte sua ideia<textarea name="body" required maxlength="6000"></textarea></label><p class="small">Os dados serão usados para responder ao orçamento. <a class="textlink" href="<?=e(url('privacidade.php'))?>">Privacidade</a></p><button class="primary">Enviar briefing ↗</button></form></main><?php require ROOT.'/includes/footer.php';?>
